import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'assets/pet-form.js':''};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:70000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<6;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 3');}return 'fail';}
const o={marker:'S230B'};
try{
  const mk=wj('POST','code-snippets/v1/snippets',{name:'S230B (temp)',code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
  let sid=null; try{sid=JSON.parse(mk).id;}catch(e){o.mk=String(mk).slice(0,120);}
  execSync('sleep 4');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:90000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('pet-form.js')) break; }catch(e){o.write='ERR';} execSync('sleep 4'); }
  if(sid!==null){ try{execSync('curl -sk '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} }
  // verifikacija: ar backend grazina naujus faktus
  try{
    const r2=execSync('curl -sk "https://dev.avesa.lt/wp-json/petshop/v1/food-search?q=josera%20chicken&species=dog"',{maxBuffer:5e6,timeout:50000}).toString();
    const b=JSON.parse(r2.slice(r2.indexOf('{'), r2.lastIndexOf('}')+1));
    const ps=(b.products||[]).slice(0,3).map(function(x){return {n:x.name.slice(0,42), prot:x.protein_sources, grain:x.has_grains, mono:x.monoprotein};});
    o.api=ps;
  }catch(e){o.api='ERR '+String(e).slice(0,80);}
}catch(e){ o.err=String(e).slice(0,200); }
putB64('s230b.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
